def test_option_named_help(runner):
    @click.command()
    @click.option("--message", "help")
    def cli(help):
        click.echo(help)

    result = runner.invoke(cli, ["--message", "value"])
    assert result.exit_code == 0, result.output
    assert result.output == "value\n"

    result = runner.invoke(cli, ["--help"])
    assert result.exit_code == 0, result.output
    assert "Usage: cli [OPTIONS]" in result.output


